INSERT INTO `scheduler_task_config` VALUES
(2,'Auto Close Visits Task','Stops all active visits that match the visit type(s) specified by the value of the global property \'visits.autoCloseVisitType\'','org.openmrs.scheduler.tasks.AutoCloseVisitsTask','2011-11-28 23:59:59','MM/dd/yyyy HH:mm:ss',86400,0,0,1,'2018-06-04 18:30:16',NULL,NULL,NULL,'8c17b376-1a2b-11e1-a51a-00248140a5eb'),
(4,'Stock Rules Evaluation Job','Checks the stock rules against the item quantity and notifies when quantity is at or below threshold','org.openmrs.module.stockmanagement.api.jobs.StockRuleEvaluationJob','2022-10-01 00:59:59','MM/dd/yyyy HH:mm:ss',86400,0,1,1,'2026-08-17 15:47:43',NULL,NULL,NULL,'5a0b041a-5796-11ed-a495-00155dc81c72'),
(5,'Stock Batch Expiry Job','Checks for stock items expiring soon and notifies inventory manager and clerk','org.openmrs.module.stockmanagement.api.jobs.StockBatchExpiryJob','2022-10-01 00:00:00','MM/dd/yyyy HH:mm:ss',86400,0,1,1,'2026-08-17 15:47:43',NULL,NULL,NULL,'911fc382-5797-11ed-a495-00155dc81c72'),
